#define	SZPAGEB		256			// Bytes in a page
#define	PGLENB		256
#define	SZPAGEW		64			// 32b words in a page
#define	PGLENW		64
#define	NPAGES		256			// Pages per sector
#define	SECTORSZB	(NPAGES * SZPAGEB)	// In bytes, not words!!
